(4, 'SOLO', 'Plan para negocios en crecimiento', 10, 11.00, 11.00, '[\"Logo superior personalizado\", \"Cambio de colores\", \"Multi tiendas\", \"Soporte prioritario\"]', 1, '2026-04-05 14:47:45'),
(5, 'Empresas', 'Plan para empresas con múltiples sucursales', 25, 25.00, 25.00, '[\"5 impresoras Bluetooth en la app\", \"25 tiendas máximo\", \"Logo superior personalizado\", \"Cambio de colores\", \"Multi tiendas\", \"Soporte prioritario\"]', 1, '2026-06-11 14:20:22'),
(6, 'Personalizado', 'Plan con funciones a medida y soporte dedicado', 25, 99.00, 99.00, '[\"10 impresoras Bluetooth en la app\", \"Funciones personalizadas a pedido\", \"Soporte prioritario dedicado\", \"25 tiendas máximo\", \"Logo superior personalizado\", \"Cambio de colores\", \"Multi tiendas\", \"Atención directa con el equipo de desarrollo\"]', 1, '2026-06-11 14:20:22');
INSERT INTO `plugins` (`id`, `plugin_id`, `name`, `version`, `description`, `author`, `is_active`, `hooks`, `admin_slots`, `store_slots`, `settings_schema`, `has_routes`, `installed_at`) VALUES
(28, 'tuu-payments', 'Tuu Payments', '1.7.0', 'Acepta pagos con tarjeta vía POS Tuu y pagos QR vía pasarela Haulmer. Configura API Keys, POS y credenciales de Haulmer.', 'SRServi', 1, '[]', '[\"sidebar\"]', '[]', '{}', 1, '2026-06-18 05:33:16');
INSERT INTO `plugin_workshop` (`id`, `plugin_id`, `user_id`, `name`, `latest_version`, `description`, `author`, `contact_email`, `logo`, `zip_path`, `downloads`, `status`, `hooks`, `admin_slots`, `store_slots`, `created_at`, `updated_at`) VALUES
(2, 'tuu-payments', 1, 'Tuu Payments', '1.7.0', '  Pagos con tarjeta vía POS Tuu y pagos QR vía Haulmer. Configura tu API Key de Tuu, agrega dispositivos POS y asígnalos\r\n   a cada tablet. Para QR, ingresa credenciales de Haulmer (Account ID, Secret Key) en la sección dorada. En modo\r\n  delivery los clientes escanean el QR de la tienda, pagan desde su celular y reciben un comprobante con su número de\r\n  pedido (A01-Z99) descargable como imagen. Verifica firma y confirma pagos automáticamente. Compatible con SII Chile\r\n  (sequence_id y reference_id).', 'Nova', 'mail@srautomatic.com', '/api/workshop/files/1775777426981-images.jpg', '/api/workshop/files/1775677941827-tuu-payments.zip', 32, 'approved', '[]', '[\"sidebar\"]', '[]', '2026-04-08 19:52:21', '2026-06-26 23:49:43');
INSERT INTO `plugin_workshop_versions` (`id`, `plugin_id`, `version`, `zip_path`, `changelog`, `status`, `created_at`) VALUES
(1, 'tuu-payments', '1.1.0', '/api/workshop/files/1775677941827-tuu-payments.zip', 'New Version', 'approved', '2026-04-08 19:52:21'),
(2, 'tuu-payments', '1.2.0', '/api/workshop/files/1775776404924-tuu-payments.zip', 'Nueva UI Y Funciones', 'approved', '2026-04-09 23:13:24'),
(3, 'tuu-payments', '1.3.0', '/api/workshop/files/1775777426981-tuu-payments.zip', 'QR Provider', 'approved', '2026-04-09 23:30:26'),
(4, 'tuu-payments', '1.5.0', '/api/workshop/files/1775778792815-tuu-payments.zip', 'New UI And QR System', 'approved', '2026-04-09 23:53:12'),
(5, 'tuu-payments', '1.6.0', '/api/workshop/files/1775779138582-tuu-payments.zip', 'Nueva UI Y Funciones', 'approved', '2026-04-09 23:58:58'),
(6, 'tuu-payments', '1.7.0', '/api/workshop/files/1775779383664-tuu-payments.zip', '  - order_number ahora es letra + 2 dígitos (A01-Z99) en TODOS los métodos de pago (tarjeta, efectivo, QR delivery)   - Único por día (verifica que no se repita en el día)   - 2,574 combinaciones por tienda por día   - Si se agotan, hace fallback a numérico', 'approved', '2026-04-10 00:03:03');
