(1, 1, 2, 'Barrer loco', NULL, 1, '09:00', '2026-04-23 15:40:01'),
(2, 1, 1, 'Vender 5000 helados en 1 dia', NULL, 4, '11:41', '2026-04-23 15:40:26'),
(3, 1, 2, 'Traficar Lapiceros', NULL, 4, '13:03', '2026-04-23 15:42:04'),
